    // Documents database stats
    let documents_database_stats = index.documents.stats(rtxn)?;
    stats.documents_database_stats = documents_database_stats;

    // Number of documents
    stats.number_of_documents = Some(index.documents.len(rtxn)? as u64);

    // Database size
    stats.database_size = index.env.info(rtxn, index.main)?.space_used;

    // Used database size
    stats.used_database_size = index.env.info(rtxn, index.main)?.space_used_by_database;

    // Primary key
    stats.primary_key = index.primary_key().map(|pk| pk.name().to_string());

    // Field distribution
    let mut field_distribution = FieldDistribution::default();
    for (field_id, name) in index.fields_distribution(rtxn)? {
        field_distribution.insert(name.to_string(), field_id as usize);
    }
    stats.field_distribution = field_distribution;

    // Creation and update dates
    stats.created_at = index.created_at;
    stats.updated_at = index.updated_at;

    Ok(stats)
}

