    /// Compute the stats of an index
    ///
    /// # Parameters
    ///
    /// - rtxn: a RO transaction for the index, obtained from `Index::read_txn()`.
    pub fn new(index: &Index, rtxn: &RoTxn) -> milli::Result<Self> {
        let mut primary_key = None;
        let mut field_distribution = FieldDistribution::default();
        let mut created_at = None;
        let mut updated_at = None;

        let database_size = rtxn.get_database_size()?;
        let used_database_size = rtxn.get_database_used_size()?;
        let number_of_documents = rtxn.get_number_of_documents()?;
        let number_of_embeddings = rtxn.get_number_of_embeddings()?;
        let number_of_embedded_documents = rtxn.get_number_of_embedded_documents()?;

        for field_name in rtxn.get_field_names() {
            let field_type = rtxn.get_field_type(field_name)?;
            let field_count = rtxn.get_field_count(field_name)?;
            field_distribution.insert(field_name.to_string(), field_count);
        }

        let created_at_timestamp = rtxn.get_database_created_at()?;
        let updated_at_timestamp = rtxn.get_database_updated_at()?;

        if let Some(timestamp) = created_at_timestamp {
            created_at = Some(OffsetDateTime::from_unix_timestamp(timestamp));
        }

        if let Some(timestamp) = updated_at_timestamp {
            updated_at = Some(OffsetDateTime::from_unix_timestamp(timestamp));
        }

        Ok(Self {
            database_size,
            used_database_size,
            number_of_documents,
            number_of_embeddings,
            number_of_embedded_documents,
            field_distribution,
            created_at,
            updated_at,
        })
    }
}

