                    rtxn,
                    db,
                    field_id,
                    left,
                    right,
                    universe,
                    &mut children_docids,
                )?;
                *docids |= children_docids;
            }
        }
    } else {
        // Perform a search at the current level
        let mut iter = db.prefix_iter(rtxn, &field_id)?;
        while let Some((key, value)) = iter.next() {
            let left_bound = key.left_bound;
            let right_bound = key.right_bound;
            if left_bound >= right_bound {
                // The range is fully contained within the bounds
                *docids |= value.docids;
            } else if right_bound <= left_bound {
                // The range is greater than the right bound
                break;
            } else {
                // The range merely intersects the bounds
                let mut children_docids = RoaringBitmap::new();
                find_docids_of_facet_within_bounds(
                    rtxn,
                    db,
                    field_id,
                    left,
                    right,
                    universe,
                    &mut children_docids,
                )?;
                *docids |= children_docids;
