pub fn ascending_facet_sort<'t>(
    rtxn: &'t heed::RoTxn<'t>,
    db: heed::Database<FacetGroupKeyCodec<BytesRefCodec>, FacetGroupValueCodec>,
    field_id: u16,
    candidates: RoaringBitmap,
) -> Result<impl Iterator<Item = Result<(RoaringBitmap, &'t [u8])>> + 't> {
    let highest_level = get_highest_level(rtxn, db, field_id)?;
    let mut stack = Vec::new();
    for level in (0..=highest_level).rev() {
        let level_prefix = {
            let mut p = Vec::with_capacity(level + 1);
            p.extend_from_slice(&field_id.to_be_bytes());
            p.push(level as u8);
            p
        };
        let iter = db
            .remap_types::<Bytes, DecodeIgnore>()
            .prefix_iter(rtxn, level_prefix.as_slice())?;
        stack.push((candidates.clone(), iter));
    }
    Ok(AscendingFacetSort {
        rtxn,
        db,
        field_id,
        stack,
    })
}

