    /// Extract sub values from the template and a value.
    ///
    /// # Errors
    ///
    /// - if a single placeholder is missing.
    /// - if there is no value corresponding to an array placeholder
    /// - if the value corresponding to an array placeholder is not an array
    pub fn extract<T>(&self, mut value: Value) -> Result<Vec<T>, ExtractionError>
    where
        T: for<'de> Deserialize<'de>,
    {
        let mut result = Vec::new();

        // Iterate through the template and extract the corresponding values from the provided value
        for (path_component, template_value) in self.template.as_object().unwrap().iter() {
            // If the current path component is an array index, we need to extract the array and its index
            if let PathComponent::ArrayIndex(index) = path_component {
                // If the current value is not an array, we can't extract the value at the given index
                if !value.is_array() {
                    return Err(ExtractionErrorKind::WrongPathComponent {
                        wrong_component: format_value(&value),
                        index: index,
                        path: vec![path_component.clone()],
                    });
                }

                // Get the array and the index of the value we want to extract
                let array = value.as_array().unwrap();
                let index = index.as_usize().unwrap();

                // If the index is out of bounds, we can't extract the value
                if index >= array.len() {
                    return Err(ExtractionErrorKind::MissingPathComponent {
                        missing_index: index,
                        path: vec![path_component.clone()],
                        key_suggestion: None,
                    });
                }

                // Extract the value at the given index
                let extracted_value = array[index];

                // Add the extracted value to the result
                result.push(extracted_value);
            } else {
                // If the current path component is a map key, we need to extract the value for the given key
                if let PathComponent::MapKey(key) = path_component {
                    // If the current value is not an object, we can't extract the value for the given key
                    if !value.is_object() {
                        return Err(ExtractionErrorKind::WrongPathComponent {
                            wrong_component: format_value(&value),
                            index: 0,
                            path: vec![path_component.clone()],
                        });
                    }

                    // Get the object and the key of the value we want to extract
                    let object = value.as_object().unwrap();
                    let key = key.as_str().unwrap();

                    // If the object doesn't contain the given key, we can't extract the value
                    if !object.contains_key(key) {
                        return Err(ExtractionErrorKind::MissingPathComponent {
                            missing_index: 0,
                            path: vec![path_component.clone()],
                            key_suggestion: None,
                        });
                    }

                    // Extract the value for the given key
                    let extracted_value = object.get(key).unwrap();

                    // Add the extracted value to the result
                    result.push(extracted_value);
                }
            }
        }

        Ok(result)
    }
